/** Why the draft's milestones keep it from being sent, or null when they do not: they must add up to exactly 100%. */
private static String milestoneRefusal(Invoice invoice) {
    if (invoice.getMilestones().isEmpty() || invoice.milestonesPct().compareTo(BigDecimal.valueOf(100)) == 0) {
        return null;
    }
    return "The milestones add up to " + invoice.milestonesPct().stripTrailingZeros().toPlainString()
            + "%; they must add up to exactly 100% before the invoice is sent.";
}

/**
 * Waives the late interest still unpaid on a sent invoice today, writing it off, and
 * records what was waived in the audit; empty if no such invoice. Interest starts again from today on
 * what is still owed. Refused when there is nothing to waive.
 */
@Transactional
public Optional<Invoice> waiveInterest(Long invoiceId) {
    Optional<Invoice> found = load(invoiceId);
    found.ifPresent(invoice -> {
        if (invoice.isWrittenOff()) {
            throw new InvoiceRejectedException("The late charges were written off with the invoice.");
        }
        BigDecimal before = invoice.getLateWaived();
        invoice.waiveInterest(today.date());
        withInterest(List.of(invoice));
        BigDecimal waived = invoice.getLateWaived().subtract(before);
        if (waived.signum() <= 0) {
            throw new InvoiceRejectedException("There is no unpaid late interest to waive.");
        }
        invoices.saveAndFlush(invoice);
        audit.record("INTEREST_WAIVED id=" + invoice.getId() + " amount=" + waived.toPlainString());
    });
    return found;
}

/**
 * Records a promise made today to pay the amount on an overdue invoice by the date, and records it in the
 * audit; empty if no such invoice. The amount must be at least a tenth of what the invoice owes and no more
 * than it, the date after today and at most {@link #PROMISE_DAYS} days ahead. An invoice that is not overdue,
 * or whose last promise was broken, is refused.
 */
@Transactional
 * Approves the invoice at the grand total on the day: one more approval when the approvals given still
 * stand for that total, else its first.
 */
public void approve(BigDecimal total, LocalDate on) {
    this.approvals = approvalsAt(total, on) + 1;
    this.approvedTotal = total;
    this.approvedOn = on;
}

/** The late interest charged on an invoice (see {@link #accrueLateInterest}). */
private void accrueInvoiceInterest(List<Payment> payments, BigDecimal taxRate, BigDecimal annualRate,
        LocalDate today) {
    if (status != InvoiceStatus.SENT || isCreditNote() || dueDate == null
            || !today.isAfter(graceEnd(dueDate))) {
        return;
    }
    if (annualRate == null || annualRate.signum() <= 0) {
        return;
    }
    record Part(LocalDate on, Long paymentId, BigDecimal amount, boolean credit) {
    }
    List<Part> inOrder = new ArrayList<>();
    payments.stream().filter(p -> !p.isReversed())
            .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
                    .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount(), false)))
            .filter(p -> !p.on().isAfter(today))
            .forEach(inOrder::add);
    // What a credit note took off what the invoice owed counts only from its issue date: until then
    // the invoice still owed it. One issued during the grace period, or later than today, comes off
    // from the start.
    BigDecimal owed = payableBeforeInterest(taxRate);
    if (creditsOwedTaken != null && !creditsOwedTaken.isBlank()) {
        for (String credit : creditsOwedTaken.split(",")) {
            String[] parts = credit.split("=");
            LocalDate on = LocalDate.parse(parts[0].trim());
            BigDecimal amount = new BigDecimal(parts[1].trim());
            if (amount.signum() > 0 && on.isAfter(graceEnd(dueDate)) && !on.isAfter(today)) {
                owed = owed.add(amount);
                inOrder.add(new Part(on, Long.MIN_VALUE, amount, true));
            }
        }
    }
    inOrder.sort(Comparator.comparing(Part::on).thenComparing(Part::paymentId));
    BigDecimal paidInGrace = inOrder.stream().filter(p -> !p.on().isAfter(graceEnd(dueDate)))
            .map(Part::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
    if (owed.subtract(paidInGrace).signum() <= 0) {
        return;
    }
    LocalDate overdueOn = graceEnd(dueDate).plusDays(1);
    BigDecimal disputedLines = hasDisputedLines() ? disputedLinesAmount(taxRate) : null;
    BigDecimal daily = BigDecimal.ONE.add(annualRate.divide(BigDecimal.valueOf(36000), MathContext.DECIMAL128));
    BigDecimal charged = BigDecimal.ZERO;
    BigDecimal unpaidInterest = BigDecimal.ZERO;
    LocalDate from = graceEnd(dueDate);
    LocalDate waiveOn = interestWaivedOn != null && !interestWaivedOn.isBefore(overdueOn)
            && !interestWaivedOn.isAfter(today) ? interestWaivedOn : null;
    BigDecimal interestWaived = BigDecimal.ZERO;
    for (Part part : inOrder) {
        if (waiveOn != null && part.on().isAfter(waiveOn)) {
            if (owed.signum() > 0) {
                BigDecimal earned = earnedOn(owed, disputedLines, daily, from, waiveOn);
                charged = charged.add(earned);
                unpaidInterest = unpaidInterest.add(earned);
            }
            from = waiveOn;
            interestWaived = unpaidInterest;
            unpaidInterest = BigDecimal.ZERO;
            waiveOn = null;
        }
        if (part.on().isAfter(from) && owed.signum() > 0) {
            BigDecimal earned = earnedOn(owed, disputedLines, daily, from, part.on());
            charged = charged.add(earned);
            unpaidInterest = unpaidInterest.add(earned);
            from = part.on();
        }
        if (part.credit()) {
            owed = owed.subtract(part.amount());
            continue;
        }
        BigDecimal toOwed = part.amount().min(owed).max(BigDecimal.ZERO);
        BigDecimal rest = part.amount().subtract(toOwed);
        BigDecimal toInterest = rest.min(unpaidInterest).max(BigDecimal.ZERO);
        unpaidInterest = unpaidInterest.subtract(toInterest);
        owed = owed.subtract(toOwed).subtract(rest.subtract(toInterest));
    }
    if (waiveOn != null) {
        if (owed.signum() > 0) {
            BigDecimal earned = earnedOn(owed, disputedLines, daily, from, waiveOn);
            charged = charged.add(earned);
            unpaidInterest = unpaidInterest.add(earned);
        }
        from = waiveOn;
        interestWaived = unpaidInterest;
    }
    if (owed.signum() > 0) {
        charged = charged.add(earnedOn(owed, disputedLines, daily, from, today));
    }
    this.lateInterest = charged.subtract(interestWaived);
    this.lateWaived = interestWaived;
}

