        BigDecimal cent = BigDecimal.ONE.movePointLeft(scale());
        for (Map.Entry<BigDecimal, List<Integer>> group : byRate(taxRate, false).entrySet()) {
            BigDecimal rate = group.getKey();
            if (rate.signum() == 0) {
